/* 第05轮创作画布：布局与叙事分离，复用导演工作台状态与操作。 */
(()=>{
 const C=Cimora,{S,M,E,path,link}=C,D=M.direction,P=M.production;
 const B=(t,a,id='',extra='')=>`<button type="button" class="cm-button ghost" data-board="${a}" data-id="${E(id)}" ${extra}>${t}</button>`;
 const state=c=>c.e.creationCanvas??={viewport:{x:20,y:20,zoom:.65},positions:{},group:0,panel:false,selected:null,branches:{},legacy:false};
 const videoCanvas=()=>S.context.parts[1]==='video'&&S.context.params.get('view')==='canvas';
 const videoThumb=(image,label)=>image?`<img src="${E(image)}" alt="${E(label)}">`:'<div class="bc-missing">画面待生成</div>';
 const shots=c=>c.c.kind==='episode'?(videoCanvas()?M.videoStoryboard.shots(c):D.ensure(c)):[];
 function frame(c){const v=state(c),ns=nodes(c),root=S.$('.bc-viewport'),w=root?.clientWidth||900,h=root?.clientHeight||500;const maxX=Math.max(900,...ns.map(n=>n.x+260)),maxY=Math.max(750,...ns.map(n=>n.y+275));v.viewport={x:18,y:25,zoom:Math.max(.25,Math.min(.8,(w-36)/maxX,(h-50)/maxY))};}
 function select(c,id){const v=state(c),n=nodes(c).find(n=>n.id===id);v.selected=id;v.panel=true;if(n?.s){c.e.selectedShotId=n.s.id;if(videoCanvas())M.videoFlow.ensure(c).selectedShotId=n.s.id;}else if(id.startsWith('shot:'))c.e.selectedShotId=id.slice(5);M.save();}
 function nodes(c){const v=state(c),ss=shots(c),out=[],allPanels=c.c.kind==='episode'?c.p.chapters.flatMap(ch=>M.ensure(c.p,ch).boards.map(b=>({b,ch}))):c.e.boards.map(b=>({b,ch:c.c}));const groups=Math.ceil((ss.length||allPanels.length)/6);v.group=Math.min(v.group,Math.max(0,groups-1));const local=ss.slice(v.group*6,v.group*6+6);const panels=c.c.kind==='episode'?allPanels.filter(({b,ch})=>local.some(s=>s.sources?.some(r=>r.chapterId===ch.id&&r.panelId===b.id))):allPanels.slice(v.group*6,v.group*6+6);
 const shotY=panels.length?(panels.length>3?570:310):40,resultY=shotY+(local.length>3?540:290);
 panels.forEach(({b,ch},i)=>out.push({id:'panel:'+b.id,title:'漫画格 · '+b.title,type:'panel',b,ch,x:20+(i%3)*270,y:20+Math.floor(i/3)*240,copy:b.action,thumb:C.comicBaseImage?.(b)||C.art(b.art,b.title),status:'来源v'+b.version}));
 local.forEach((s,i)=>{const adopted=s.candidates.find(x=>x.id===s.adoptedId);out.push({id:'shot:'+s.id,title:(v.group*6+i+1)+'. '+s.title,type:'shot',s,x:40+(i%3)*290,y:shotY+Math.floor(i/3)*260,copy:s.intent,thumb:videoCanvas()?videoThumb(adopted?.image,s.title):C.comicShotImage?.(s)||C.art(s.art,s.title),status:(s.direction.locked?'🔒 ':'')+(adopted?'采用v'+adopted.version:'未采用')+' / '+s.candidates.length+'候选'});if(v.branches[s.id]){s.candidates.slice(0,6).forEach((a,j)=>out.push({id:'candidate:'+a.id,type:'candidate',s,a,title:'候选v'+a.version+(a.id===s.adoptedId?' · 已采用':''),x:960+j%2*270,y:100+Math.floor(j/2)*235,copy:a.input.intent,thumb:videoCanvas()?videoThumb(a.image,"候选v"+a.version):a.media?`<video muted preload="metadata" src="${E(a.media.playbackUrl||a.media.url)}"></video>`:C.art(s.art,'历史流程记录'),status:a.status==='failed'?'失败':a.id===s.adoptedId?'采用v'+a.version:'待采用v'+a.version}));}if(adopted)out.push({id:'result:'+s.id,type:'result',s,a:adopted,title:'采用成品 · v'+adopted.version,x:40+(i%3)*290,y:resultY+Math.floor(i/3)*230,copy:s.direction.adoption?.label||'已采用',thumb:videoCanvas()?videoThumb(adopted.image,"采用v"+adopted.version):adopted.media?`<video muted preload="metadata" src="${E(adopted.media.playbackUrl||adopted.media.url)}"></video>`:C.art(s.art,'历史采用记录'),status:'采用v'+adopted.version+' · 保留历史'});});
 const selected=local.find(s=>'shot:'+s.id===v.selected)||local.find(s=>s.id===c.e.selectedShotId);(selected?.direction.references||[]).forEach((r,i)=>out.push({id:'ref:'+i,type:'ref',title:(D.purposes[r.purpose]||'参考')+' · '+(r.snapshot.name||r.snapshot.title),x:960+(i%2)*270,y:850+Math.floor(i/2)*230,copy:'固定引用v'+r.version+'；仅本镜用途',thumb:r.kind==='source'?C.comicBaseImage(r.snapshot):C.art(r.snapshot.art||0,r.snapshot.name),status:'素材引用 · '+D.purposes[r.purpose]}));return out.map(n=>({...n,...v.positions[n.id]}));}
 function edges(c,ns){const v=state(c),selected=ns.find(n=>n.id===v.selected),sid=selected?.s?.id||(v.selected?.startsWith('shot:')?v.selected.slice(5):null),list=[];const add=(a,b,label,kind)=>{if(a&&b)list.push({a,b,label,kind});};if(sid){const s=shots(c).find(s=>s.id===sid),sn=ns.find(n=>n.id==='shot:'+sid);s?.sources?.forEach(r=>add(ns.find(n=>n.id==='panel:'+r.panelId),sn,'漫画来源','source'));ns.filter(n=>n.type==='ref').forEach(n=>add(n,sn,'参考用途','reference'));ns.filter(n=>n.type==='candidate'&&n.s.id===sid).forEach(n=>add(sn,n,'候选分支','candidate'));add(sn,ns.find(n=>n.id==='result:'+sid),'显式采用','adopt');const ss=shots(c),i=ss.findIndex(s=>s.id===sid);add(ns.find(n=>n.id==='shot:'+ss[i-1]?.id),sn,'镜头叙事顺序','play');add(sn,ns.find(n=>n.id==='shot:'+ss[i+1]?.id),'镜头叙事顺序','play');}else if(selected?.type==='panel'){ns.filter(n=>n.type==='shot'&&n.s.sources.some(r=>r.panelId===selected.b.id)).forEach(n=>add(selected,n,'漫画来源','source'));}return list.map(({a,b,label,kind})=>`<g class="bc-edge ${kind}"><path d="M${a.x+240} ${a.y+95} C${a.x+280} ${a.y+95},${b.x-40} ${b.y+95},${b.x} ${b.y+95}"/><text x="${(a.x+240+b.x)/2}" y="${(a.y+b.y)/2+80}">${label}</text></g>`).join('');}
 function inspector(c){const v=state(c);if(!v.panel)return '';const ns=nodes(c),n=ns.find(n=>n.id===v.selected);if(!n)return '';if(videoCanvas()&&n.s)return `<aside class="bc-inspector"><header><strong>分镜 ${shots(c).indexOf(n.s)+1} · ${E(n.s.title)}</strong>${B('关闭并返回画布','close')}</header><div class="bc-inspector-body">${C.videoCanvasShotEditor(c,n.s)}</div></aside>`;if(n.type==='shot'||n.type==='candidate'||n.type==='result'){return `<aside class="bc-inspector"><header><strong>就地调优 · ${E(n.s.title)}${n.a?' · v'+n.a.version:''}${n.s.direction.locked?' · 已锁定':''}</strong>${B('关闭并返回画布','close')}</header><div class="bc-inspector-body">${C.productionMotion(c)}</div></aside>`;}if(n.type==='panel'){const matches=(c.p.episodes||[]).flatMap(ep=>P.shots(M.ensure(c.p,ep)).filter(s=>s.sources?.some(r=>r.chapterId===n.ch.id&&r.panelId===n.b.id)).map(s=>({ep,s})));return `<aside class="bc-inspector"><header><strong>漫画来源 · ${E(n.b.title)}</strong>${B('关闭并返回画布','close')}</header><div class="bc-inspector-body">${n.thumb}<p>${E(n.b.action)}</p>${C.comicSourceDetails(n.b)}<h3>相关动画镜头与候选</h3>${matches.map(({ep,s})=>c.c.id===ep.id?B(E(s.title)+' / '+s.candidates.length+'候选','locate',s.id):link(E(ep.title+' / '+s.title+' / '+s.candidates.length+'候选'),path({p:c.p,c:ep},'motion','canvas')+'&boardShot='+s.id,'cm-button ghost')).join('')||'<p>尚未关联独立动画镜头。</p>'}</div></aside>`;}return `<aside class="bc-inspector"><header><strong>${E(n.title)}</strong>${B('关闭并返回画布','close')}</header><p>${E(n.copy)}</p><p>这里只引用资产，不复制或改写素材文件。</p></aside>`;}
 const oldCanvas=C.canvas;C.canvas=c=>{const v=state(c);if(v.legacy&&!videoCanvas())return `<div class="bc-template-return">${B('返回创作画布','legacy')}</div>`+oldCanvas(c);const ns=nodes(c),panelCount=ns.filter(n=>n.type==='panel').length,shotY=panelCount?(panelCount>3?570:310):40,resultY=shotY+(ns.filter(n=>n.type==='shot').length>3?540:290),total=shots(c).length||c.e.boards.length,count=Math.ceil(total/6);return `<section class="bc-shell"><header class="bc-toolbar"><strong>创作画布</strong><span>位置自由；剪辑播放顺序另行编排</span>${videoCanvas()?'':B('流程编辑','flow')+B('模板步骤视图','legacy')}${B('适应本段','fit')}${B('整理本段','arrange')}${videoCanvas()?'':B('新建独立镜头','new-shot','',c.c.kind!=='episode'?'disabled':'')}</header><div class="bc-groups">${Array.from({length:Math.max(1,count)},(_,i)=>B('段落'+(i+1)+' · '+Math.min(6,total-i*6)+'项','group',String(i))).join('')}<small>每段最多6项摘要，选中后查看关联；候选默认收起。</small></div><div class="bc-layout"><div class="bc-viewport" tabindex="0" aria-label="创作画布，拖标题移动，空白平移，滚轮缩放"><div class="bc-world" style="transform:translate(${v.viewport.x}px,${v.viewport.y}px) scale(${v.viewport.zoom})"><svg width="2400" height="2000" class="bc-edges">${edges(c,ns)}</svg>${panelCount?'<div class="bc-band" style="top:0">漫画分格组</div>':''}<div class="bc-band" style="top:${shotY-30}px">动画镜头组 · 编号为镜头叙事顺序</div><div class="bc-band" style="top:${resultY-30}px">采用成品 / 候选与素材引用 →</div>${ns.map(n=>`<article class="bc-card ${v.selected===n.id?'selected':''} ${n.type}" data-bc-node="${E(n.id)}" style="left:${n.x}px;top:${n.y}px"><header data-bc-drag="${E(n.id)}">${E(n.title)} <span>⠿</span></header><button class="bc-card-body" data-board="select" data-id="${E(n.id)}">${n.thumb}<strong>${E(n.status)}</strong><p>${E(n.copy)}</p></button>${n.type==='shot'?`<footer>${B(v.branches[n.s.id]?'收起候选':'展开候选','branch',n.s.id)}${videoCanvas()?'':B('复制为新镜头','duplicate',n.s.id)}</footer>`:''}</article>`).join('')}</div><div class="bc-zoom">${B('−','zoom-out')}<span>${Math.round(v.viewport.zoom*100)}%</span>${B('＋','zoom-in')}</div><div class="bc-legend">仅选中项关联：紫色参考/来源 · 虚线镜头叙事顺序 · 金色采用</div></div>${inspector(c)}</div></section>`;};
 C.creationCanvasView=C.canvas;
 const oldStudio=C.studio;C.studio=c=>c.e.view==='canvas'?`<div class="bc-page">${C.canvas(c)}</div>`:`<div class="bc-flow-return">${B('进入创作画布','canvas')}</div>`+oldStudio(c);
 const oldBind=C.bindCanvas;C.bindCanvas=()=>{if(S.$('.bc-viewport'))bind();else oldBind();};
 function bind(){const root=S.$('.bc-viewport'),c=C.ctx(),v=state(c),world=root.querySelector('.bc-world');let drag;const transform=()=>{world.style.transform=`translate(${v.viewport.x}px,${v.viewport.y}px) scale(${v.viewport.zoom})`;root.querySelector('.bc-zoom span').textContent=Math.round(v.viewport.zoom*100)+'%';};root.addEventListener('pointerdown',e=>{if(e.button!==0||e.target.closest('button,input,select'))return;const h=e.target.closest('[data-bc-drag]'),n=h&&nodes(c).find(n=>n.id===h.dataset.bcDrag);if(e.target.closest('.bc-card')&&!n)return;drag={x:e.clientX,y:e.clientY,n,vx:v.viewport.x,vy:v.viewport.y};root.setPointerCapture(e.pointerId);e.preventDefault();});root.addEventListener('pointermove',e=>{if(!drag)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(drag.n){const n=drag.n,pos={x:Math.max(0,n.x+dx/v.viewport.zoom),y:Math.max(0,n.y+dy/v.viewport.zoom)};v.positions[n.id]=pos;const el=root.querySelector(`[data-bc-node="${n.id}"]`);el.style.left=pos.x+'px';el.style.top=pos.y+'px';root.querySelector('.bc-edges').innerHTML=edges(c,nodes(c));}else{v.viewport.x=drag.vx+dx;v.viewport.y=drag.vy+dy;transform();}});const end=()=>{if(!drag)return;drag=null;M.save();S.render();};root.addEventListener('pointerup',end);root.addEventListener('pointercancel',end);root.addEventListener('wheel',e=>{e.preventDefault();const r=root.getBoundingClientRect(),px=e.clientX-r.left,py=e.clientY-r.top,z=Math.min(1.4,Math.max(.25,v.viewport.zoom*(e.deltaY<0?1.1:.9)));v.viewport.x=px-(px-v.viewport.x)*z/v.viewport.zoom;v.viewport.y=py-(py-v.viewport.y)*z/v.viewport.zoom;v.viewport.zoom=z;transform();M.save();},{passive:false});}
 document.addEventListener('click',ev=>{const el=ev.target.closest('[data-board]');if(!el)return;ev.preventDefault();ev.stopImmediatePropagation();const c=C.ctx(),v=state(c),id=el.dataset.id;if(videoCanvas())try{C.flushVideoStoryboard?.();}catch(error){S.toast(error.message);return;}switch(el.dataset.board){case'select':select(c,id);break;case'close':v.panel=false;break;case'canvas':S.route(path(c,c.e.stage,'canvas'));return;case'flow':S.route(path(c,c.e.stage,'flow'));return;case'legacy':v.legacy=!v.legacy;break;case'group':v.group=Number(id);v.panel=false;v.selected=null;v.viewport={x:20,y:20,zoom:.55};break;case'branch':{const open=!v.branches[id];v.branches={};v.branches[id]=open;break;}case'locate':v.group=Math.floor(shots(c).findIndex(s=>s.id===id)/6);v.branches[id]=true;select(c,'shot:'+id);break;case'zoom-in':case'zoom-out':v.viewport.zoom=Math.min(1.4,Math.max(.25,v.viewport.zoom*(el.dataset.board==='zoom-in'?1.15:1/1.15)));break;case'arrange':nodes(c).forEach(n=>delete v.positions[n.id]);frame(c);break;case'fit':frame(c);break;case'new-shot':{const error=D.blocked(c);if(error){S.toast(error);return;}const s=M.adaptation.add(c,{title:'新建独立镜头',intent:'在此输入剧情意图',sources:[]});D.ensure(c);v.group=Math.floor(shots(c).indexOf(s)/6);select(c,'shot:'+s.id);frame(c);break;}case'duplicate':{const error=D.blocked(c);if(error){S.toast(error);return;}const s=D.shot(c,id),n=M.adaptation.add(c,{title:s.title+' · 新镜头',intent:s.intent,dialogue:s.dialogue,duration:s.duration,art:s.art,sources:M.clone(s.sources)});D.ensure(c);n.direction=M.clone(s.direction);n.direction.locked=false;delete n.direction.adoption;select(c,'shot:'+n.id);v.group=Math.floor(shots(c).indexOf(n)/6);frame(c);S.toast('已新建镜头；引用原资产，不复制候选/采用/锁定');break;}}M.save();S.render();},true);
 let routeFocus=null;const oldAfter=C.afterRender;C.afterRender=r=>{const c=C.ctx();if(c?.e.view==='canvas'&&c.e.canvasFocus?.active){oldAfter(r);return;}if(c?.e.view==='canvas'){const v=state(c),n=nodes(c).find(n=>n.id===v.selected);if(v.panel&&n?.s&&n.s.id!==c.e.selectedShotId){v.group=Math.floor(shots(c).findIndex(s=>s.id===c.e.selectedShotId)/6);v.selected='shot:'+c.e.selectedShotId;M.save();S.render();return;}const id=r.params.get('boardShot'),key=c.c.id+'|'+id;if(!id)routeFocus=null;if(id&&shots(c).some(s=>s.id===id)&&routeFocus!==key){routeFocus=key;state(c).group=Math.floor(shots(c).findIndex(s=>s.id===id)/6);select(c,'shot:'+id);state(c).branches[id]=true;S.render();return;}}oldAfter(r);};
})();

